Here’s a **simple and clean C program** to manage bank accounts using **structures and pointers** 👇  

```c
#include <stdio.h>
#include <string.h>

struct BankAccount {
    int accNumber;
    char holderName[50];
    float balance;
};

void showAccount(struct BankAccount *acc) {
    printf("\n--- Account Details ---\n");
    printf("Account Number: %d\n", acc->accNumber);
    printf("Holder Name: %s\n", acc->holderName);
    printf("Balance: %.2f\n", acc->balance);
}

void deposit(struct BankAccount *acc, float amount) {
    acc->balance += amount;
    printf("Deposited %.2f successfully!\n", amount);
}

void withdraw(struct BankAccount *acc, float amount) {
    if (amount > acc->balance) {
        printf("Insufficient balance!\n");
    } else {
        acc->balance -= amount;
        printf("Withdrawn %.2f successfully!\n", amount);
    }
}

int main() {
    struct BankAccount acc1;
    struct BankAccount *ptr = &acc1;

    // Input account details
    printf("Enter account number: ");
    scanf("%d", &ptr->accNumber);
    getchar(); // to consume newline

    printf("Enter holder name: ");
    fgets(ptr->holderName, sizeof(ptr->holderName), stdin);
    ptr->holderName[strcspn(ptr->holderName, "\n")] = '\0'; // remove newline

    printf("Enter initial balance: ");
    scanf("%f", &ptr->balance);

    int choice;
    float amount;

    do {
        printf("\n--- Bank Menu ---\n");
        printf("1. Show Account\n");
        printf("2. Deposit\n");
        printf("3. Withdraw\n");
        printf("4. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                showAccount(ptr);
                break;
            case 2:
                printf("Enter amount to deposit: ");
                scanf("%f", &amount);
                deposit(ptr, amount);
                break;
            case 3:
                printf("Enter amount to withdraw: ");
                scanf("%f", &amount);
                withdraw(ptr, amount);
                break;
            case 4:
                printf("Exiting... Thank you!\n");
                break;
            default:
                printf("Invalid choice!\n");
        }
    } while (choice != 4);

    return 0;
}
```

### 🔹 What it does:
- Uses a **structure** to store account details.  
- Uses a **pointer** to access and modify structure members.  
- Lets the user **view, deposit, or withdraw** money interactively.  

