**Title:** Write a C++ program to add two complex numbers by passing structure to a function.  

**Description:**  
A structure in C++ is a collection of variables of different data types grouped under one name.  
This program defines a structure named `Complex` with real and imaginary parts as members.  
The program demonstrates how to pass structures to a function to add two complex numbers and return the result.

---

### **Program:**
```cpp
#include <iostream>
using namespace std;

// Structure definition
struct Complex {
    float real;
    float imag;
};

// Function to add two complex numbers
Complex addComplex(Complex c1, Complex c2) {
    Complex result;
    result.real = c1.real + c2.real;
    result.imag = c1.imag + c2.imag;
    return result;
}

// Function to display a complex number
void display(Complex c) {
    cout << c.real << " + " << c.imag << "i" << endl;
}

int main() {
    Complex num1, num2, sum;

    cout << "Enter first complex number:\n";
    cout << "Real part: ";
    cin >> num1.real;
    cout << "Imaginary part: ";
    cin >> num1.imag;

    cout << "\nEnter second complex number:\n";
    cout << "Real part: ";
    cin >> num2.real;
    cout << "Imaginary part: ";
    cin >> num2.imag;

    // Pass structures to function
    sum = addComplex(num1, num2);

    cout << "\nThe sum of the two complex numbers is: ";
    display(sum);

    return 0;
}
```

