### **Practical No-6**  
**Date:** 1 / 9 / 2024  

**Title:** Write a C++ program to perform addition, subtraction, and multiplication of two complex numbers by passing structure to a function.  

**Description:**  
A structure can hold related data of different types under one name.  
In this program, we define a structure `Complex` with members `real` and `imag`.  
We then pass these structures to functions to perform **addition**, **subtraction**, and **multiplication** of complex numbers, returning the result as another structure.  

---

### **Program:**
```cpp
#include <iostream>
using namespace std;

// Structure definition
struct Complex {
    float real;
    float imag;
};

// Function to add two complex numbers
Complex addComplex(Complex c1, Complex c2) {
    Complex result;
    result.real = c1.real + c2.real;
    result.imag = c1.imag + c2.imag;
    return result;
}

// Function to subtract two complex numbers
Complex subtractComplex(Complex c1, Complex c2) {
    Complex result;
    result.real = c1.real - c2.real;
    result.imag = c1.imag - c2.imag;
    return result;
}

// Function to multiply two complex numbers
Complex multiplyComplex(Complex c1, Complex c2) {
    Complex result;
    result.real = (c1.real * c2.real) - (c1.imag * c2.imag);
    result.imag = (c1.real * c2.imag) + (c1.imag * c2.real);
    return result;
}

// Function to display a complex number
void display(Complex c) {
    cout << c.real << " + " << c.imag << "i" << endl;
}

int main() {
    Complex num1, num2, sum, diff, prod;

    cout << "Enter first complex number:\n";
    cout << "Real part: ";
    cin >> num1.real;
    cout << "Imaginary part: ";
    cin >> num1.imag;

    cout << "\nEnter second complex number:\n";
    cout << "Real part: ";
    cin >> num2.real;
    cout << "Imaginary part: ";
    cin >> num2.imag;

    // Operations
    sum = addComplex(num1, num2);
    diff = subtractComplex(num1, num2);
    prod = multiplyComplex(num1, num2);

    cout << "\nAddition: ";
    display(sum);

    cout << "Subtraction: ";
    display(diff);

    cout << "Multiplication: ";
    display(prod);

    return 0;
}
```

